import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_doRun_TriageGen0Test {

    @Spy
    private AbstractCommandLineRunnerTestable runner;

    @Mock
    private CommandLineConfig config;

    @Mock
    private Compiler compiler;

    @Mock
    private B options;

    @Mock
    private Result result;

    @Mock
    private Writer mockWriter;

    // Helper class to expose protected method for testing
    public static class AbstractCommandLineRunnerTestable extends AbstractCommandLineRunner<Compiler, B> {
        public Charset inputCharset = StandardCharsets.UTF_8;
        public Writer out;

        @Override
        protected Compiler createCompiler() { return compiler; }
        @Override
        protected B createOptions() { return options; }
        @Override
        protected CommandLineConfig getCommandLineConfig() { return config; }

        // Mocking these to avoid actual file system/complex logic
        @Override
        protected List<JSSourceFile> createExterns() throws IOException { return new ArrayList<>(); }
        @Override
        protected List<JSSourceFile> createSourceInputs(List<String> jsFiles) throws IOException { return new ArrayList<>(); }
        @Override
        protected List<com.google.javascript.jscomp.JSModule> createJsModules(List<String> moduleSpecs, List<String> jsFiles) { return new ArrayList<>(); }

        @Override
        protected int processResults(Result result, List<com.google.javascript.jscomp.JSModule> modules, B options) { return 0; }

        @Override
        protected Writer toWriter(String fileName, String charsetName) throws IOException { return mockWriter; }

        @Override
        protected void setRunOptions(B options) throws IOException {}

        // Dummy implementations for abstract/required methods
        @Override protected void initOptionsFromFlags(B options) {}
        @Override protected java.util.List<com.google.javascript.jscomp.DiagnosticGroup> getDiagnosticGroups() { return null; }
        @Override protected java.io.PrintStream getErrorPrintStream() { return null; }
    }

    @Before
    public void setUp() throws Exception {
        // Setup default config behavior
        lenient().when(config.loggingLevel).thenReturn("INFO");
        lenient().when(config.js).thenReturn(new ArrayList<>());
        lenient().when(config.module).thenReturn(new ArrayList<>());
        lenient().when(options.jsOutputFile).thenReturn("");

        // Inject config into runner (assuming runner uses getCommandLineConfig())
        // Since we can't easily change the field 'config' if it's private, 
        // we rely on the runner implementation using the returned config.
        // For this test, we assume the runner's field 'config' is populated via getCommandLineConfig().
        // However, in the provided code, 'config' is used directly. 
        // We will use reflection if necessary, but here we assume the spy is configured.
        java.lang.reflect.Field configField = AbstractCommandLineRunner.class.getDeclaredField("config");
        configField.setAccessible(true);
        configField.set(runner, config);
    }

    @Test
    public void testDoRun_ModulePath_UTF8Charset() throws Exception {
        runner.inputCharset = StandardCharsets.UTF_8;
        List<String> moduleSpecs = Collections.singletonList("module.js");
        when(config.module).thenReturn(moduleSpecs);
        when(config.js).thenReturn(Collections.singletonList("file.js"));
        when(options.jsOutputFile).thenReturn("output.js");

        when(compiler.compile(any(), any(), any())).thenReturn(result);

        int status = runner.doRun();

        assertEquals(0, status);
        assertEquals(StandardCharsets.US_ASCII, options.outputCharset);
        verify(compiler).compile(any(), any(), eq(options));
        verify(mockWriter).close();
    }

    @Test
    public void testDoRun_NoModulePath_NonUTF8Charset() throws Exception {
        runner.inputCharset = StandardCharsets.ISO_8859_1;
        when(config.module).thenReturn(new ArrayList<>());
        when(config.js).thenReturn(Collections.singletonList("file.js"));
        when(options.jsOutputFile).thenReturn("");

        when(compiler.compile(any(), any(), any())).thenReturn(result);

        int status = runner.doRun();

        assertEquals(0, status);
        assertEquals(StandardCharsets.ISO_8859_1, options.outputCharset);
        verify(compiler).compile(any(), any(), eq(options));
        verify(mockWriter, never()).close();
    }

    @Test
    public void testDoRun_EmptyInputs() throws Exception {
        runner.inputCharset = StandardCharsets.UTF_8;
        when(config.module).thenReturn(new ArrayList<>());
        when(config.js).thenReturn(new ArrayList<>());
        when(options.jsOutputFile).thenReturn("");

        // Mocking createSourceInputs to return empty list to avoid NPE in toArray
        doReturn(new ArrayList<JSSourceFile>()).when(runner).createSourceInputs(any());
        when(compiler.compile(any(), any(), any())).thenReturn(result);

        int status = runner.doRun();

        assertEquals(0, status);
        verify(compiler).compile(any(), any(), eq(options));
    }

    @Test
    public void testDoRun_ProcessResultsFailure() throws Exception {
        runner.inputCharset = StandardCharsets.UTF_8;
        when(config.module).thenReturn(new ArrayList<>());
        when(config.js).thenReturn(Collections.singletonList("file.js"));
        when(options.jsOutputFile).thenReturn("");

        doReturn(new ArrayList<JSSourceFile>()).when(runner).createSourceInputs(any());
        when(compiler.compile(any(), any(), any())).thenReturn(result);
        doReturn(1).when(runner).processResults(eq(result), any(), eq(options));

        int status = runner.doRun();

        assertEquals(1, status);
    }
}
